flags.typeql:
with fun interacts1_total($c: character) -> integer:
    match $r1 isa interacts1 (character1: $c);
    $r1 has weight $w1;
    return sum($w1);
with fun interacts2_total($c: character) -> integer:
    match $r2 isa interacts2 (character1: $c);
    $r2 has weight $w2;
    return sum($w2);
match
$c isa character;
let $total = interacts1_total($c) + interacts2_total($c);
sort $total desc;
limit 5;
fetch {
    "characterName": $c.name,
    "totalWeight": $total
};

match
$c isa character, has name $name;
$c has centrality $cent;
$c has book1_betweenness_centrality $b1bc;
$c has book1_page_rank $b1pr;
$c has book45_page_rank $b45pr;
let $total = $cent + $b1bc + $b1pr + $b45pr;
sort $total desc;
limit 3;
fetch {
  "characterName": $name,
  "totalCentrality": $total
};

match
$c isa character, has louvain $l, has pagerank $pr;
$l == 10;
$pr > 0.5;
fetch {
  "name": $c.name,
  "louvain": $l,
  "pagerank": $pr
};

match
$c isa character, has community 578, has community 579;
limit 5;
fetch { "name": $c.name };

match
$c isa character, has book1_page_rank $b1, has book45_page_rank $b45, has name $name;
let $total = $b1 + $b45;
sort $total desc;
limit 3;
fetch {
  "characterName": $name,
  "totalPageRank": $total
};

match
$c isa character, has community 759, has book1_betweenness_centrality $b;
sort $b desc;
limit 3;
fetch {
  "name": $c.name,
  "book1_betweenness_centrality": $b
};

match
$c isa character, has book1_page_rank $b1, has book45_page_rank $b45, has pagerank $pr;
let $total = $b1 + $b45 + $pr;
sort $total desc;
limit 5;
fetch {
  "characterName": $c.name,
  "totalPageRank": $total
};

match
$c isa character;
$c has centrality $cent;
$c has book1_betweenness_centrality $b1bc;
$c has book1_page_rank $b1pr;
$c has book45_page_rank $b45pr;
let $avg_centrality = ($cent + $b1bc + $b1pr + $b45pr) / 4.0;
sort $avg_centrality desc;
limit 5;
fetch {
  "characterName": $c.name,
  "avgCentrality": $avg_centrality
};

match
$c isa character, has centrality 0.8;
limit 5;
fetch {
  "name": $c.name
};

match
$c isa character, has louvain $l, has name $n;
$l < 5;
sort $l;
limit 5;
fetch {
  "name": $n,
  "louvain": $l
};

match
$c isa character, has community 504;
limit 3;
fetch {
  "name": $c.name,
  "community": $c.community
};

match
$c isa character, has community 735;
limit 3;
fetch {
  "name": $c.name,
  "community": $c.community
};

match
$c isa character, has louvain 6;
fetch {
  "name": $c.name
};

match
$c isa character, has book45_page_rank $r;
$r < 0.7;
sort $r asc;
limit 3;
fetch {
  "name": $c.name,
  "book45_page_rank": $r
};

match
$c isa character, has louvain 1;
limit 3;
fetch { "name": $c.name };

match
$c isa character, has community $comm, has name $n;
$comm == 642;
limit 3;
fetch {
  "name": $n,
  "community": $comm
};

match
$c isa character, has community 579;
limit 5;
fetch {
  "name": $c.name
};
